import React from "react";

// Light markdown for agent/LLM output: **bold**, bullet lists, ### headings.
// Deliberately tiny — no raw-HTML injection, everything stays JSX.
//
// Extracted from UserSpace.js so the Jarvis page can render assistant answers
// the same way the workspace does, without a second copy drifting from this one.
// Callers style it through the `.md-lite` wrapper class.
export default function MdLite({ text }) {
  if (!text) return null;
  // **bold** and `code`. Split on both in one pass so either can appear
  // anywhere in a line — assistant answers mix them constantly.
  const inline = (s) => {
    const parts = String(s).split(/(\*\*[^*]+\*\*|`[^`]+`)/g);
    return parts.map((p, i) => {
      if (p.startsWith("**") && p.endsWith("**")) {
        return <strong key={i}>{p.slice(2, -2)}</strong>;
      }
      if (p.startsWith("`") && p.endsWith("`") && p.length > 2) {
        return <code key={i}>{p.slice(1, -1)}</code>;
      }
      return p;
    });
  };
  const lines = String(text).split("\n");
  const out = [];
  let list = null;
  // Fenced code blocks. Without this the ``` markers render as literal
  // backticks and the code inside gets word-wrapped as prose, which is how
  // most answers containing code used to look.
  let fence = null;
  let fenceLang = "";
  const flushList = (key) => {
    if (list) {
      out.push(<ul key={`ul-${key}`}>{list}</ul>);
      list = null;
    }
  };
  lines.forEach((line, i) => {
    const trimmed = line.trim();

    // ``` opens a block, the next ``` closes it. An unterminated fence at the
    // end of the text is still rendered — answers stream in, so a block is
    // half-open for as long as it takes to arrive.
    if (trimmed.startsWith("```")) {
      if (fence === null) {
        flushList(i);
        fence = [];
        fenceLang = trimmed.slice(3).trim();
      } else {
        out.push(
          <pre
            key={`pre-${i}`}
            className={fenceLang ? `lang-${fenceLang}` : undefined}
          >
            <code>{fence.join("\n")}</code>
          </pre>
        );
        fence = null;
        fenceLang = "";
      }
      return;
    }
    if (fence !== null) {
      fence.push(line);
      return;
    }

    if (/^([-•*]|\d+[.)])\s+/.test(trimmed)) {
      if (!list) list = [];
      list.push(
        <li key={i}>{inline(trimmed.replace(/^([-•*]|\d+[.)])\s+/, ""))}</li>
      );
      return;
    }
    flushList(i);
    if (/^#{1,4}\s/.test(trimmed)) {
      out.push(<h5 key={i}>{inline(trimmed.replace(/^#{1,4}\s/, ""))}</h5>);
    } else if (trimmed) {
      out.push(<p key={i}>{inline(trimmed)}</p>);
    }
  });
  flushList("end");
  // A fence still open when the text ends (mid-stream, or the model never
  // closed it) — render what we have rather than dropping it silently.
  if (fence !== null && fence.length) {
    out.push(
      <pre key="pre-open">
        <code>{fence.join("\n")}</code>
      </pre>
    );
  }
  return <div className="md-lite">{out}</div>;
}
